UPDATE ad SET item_id=#{ad.itemId},title=#{ad.title},landing_url=#{ad.landingUrl},quality_score=#{ad.qualityScore},status=#{ad.status},
    review_status=#{ad.reviewStatus},review_reason=#{ad.reviewReason},optimization_type=#{ad.optimizationType},target_cpa=#{ad.targetCpa},audience_id=#{ad.audienceId}
    WHERE advertiser_id=#{ad.advertiserId} AND ad_id=#{ad.adId}
